{"code": "import os, re, openpyxl

ws = "/workspace/dumps/workspace"

wb = openpyxl.load_workbook(os.path.join(ws, "CollegeNameID.xlsx"), data_only=True)
table = {}
for sheet in wb.sheetnames:
    ws_obj = wb[sheet]
    for row in ws_obj.iter_rows(min_row=2, values_only=True):
        if row[0] is None:
            continue
        name = str(row[0]).strip()
        sid = row[1]
        college = str(row[2]).strip()
        table[name] = (college, str(int(sid)))

# OS HW3 files (from previous classification)
files = sorted(os.listdir(ws))
os3 = []
for f in files:
    p = os.path.join(ws, f)
    if os.path.isdir(p):
        continue
    with open(p, 'r', encoding='utf-8', errors='replace') as fh:
        c = fh.read()
    if "Operating Systems Assignment 3" in c and "Operating Systems HW3" in c:
        os3.append(f)

print("OS HW3 files:", len(os3))

# Extract student name: prefix before first '-' or '_'
def student_name(fname):
    m = re.match(r"^(.+?)[-_]", fname)
    return m.group(1) if m else None

unknown, dup, missing = [], [], []
seen = {}
for f in os3:
    nm = student_name(f)
    if nm is None or nm not in table:
        unknown.append((f, nm))
    else:
        seen.setdefault(nm, []).append(f)

for nm, fl in seen.items():
    if len(fl) > 1:
        dup.append((nm, fl))

for nm in table:
    if nm not in seen:
        missing.append(nm)

print("Unknown/unmapped:", unknown)
print("Duplicates:", dup)
print("Missing students (no file):", missing)

# Verify extensions
from collections import Counter
exts = Counter(os.path.splitext(f)[1].lower() for f in os3)
print("Extensions:", exts)

# Show full mapping preview
print("\nMapping (name -> college, id, ext):")
for f in sorted(os3):
    nm = student_name(f)
    col, sid = table[nm]
    print(f"{f}  =>  {nm}-{col}-{sid}-OS-HW3{os.path.splitext(f)[1]}")
"}

