]

line_re = re.compile(r'^(\s*"[^"]+"): (")(.*)(")(,?)$', re.S)

def repair_text(text):
    out_lines = []
    for line in text.splitlines():
        m = line_re.match(line)
        if m:
            prefix, value, closing, comma = m.group(1), m.group(3), m.group(4), m.group(5)
            value_esc = value.replace('"', '\\"')
            out_lines.append(f'{prefix}: "{value_esc}"{closing}{comma}')
        else:
            out_lines.append(line)
    return "\n".join(out_lines)

all_products = {}
for path in files:
    with open(path) as f:
        content = f.read()
    start = content.find('[')
    end = content.rfind(']')
    raw = content[start:end+1]
    repaired = repair_text(raw)
    try:
        data = json.loads(repaired)
    except json.JSONDecodeError as e:
        print("FAILED to parse", path, e)
        print(repaired[max(0,e.pos-150):e.pos+150])
        continue
    print(path.split('/')[-1], "->", len(data), "products")
    for p in data:
