1: #!/usr/bin/env node
2: 
3: /**
4:  * Toolathlon's Gateway speaks the legacy MCP Classic SSE transport while DSH's
5:  * built-in MCP client speaks stdio.  This process is deliberately a protocol
6:  * bridge only: it forwards MCP requests and responses without changing tool
7:  * names, descriptions, or schemas.
8:  */
9: 
10: const gatewayUrl = process.argv[2] || process.env.TOOLATHLON_MCP_GATEWAY_URL
11: const supportedProtocolVersions = new Set([
12:   '2025-11-25',
13:   '2025-06-18',
14:   '2025-03-26',
15:   '2024-11-05',
16:   '2024-10-07',
17: ])
18: 
19: class RpcError extends Error {
20:   constructor(code, message, data) {
21:     super(message)
22:     this.name = 'RpcError'
23:     this.code = code
24:     this.data = data
25:   }
26: }
27: 
28: function fail(message) {
29:   process.stderr.write(`toolathlon-sse-stdio: ${message}\n`)
30:   process.exitCode = 1
31: }
32: 
33: function assertGatewayUrl(value) {
34:   if (!value) throw new Error('missing Gateway URL')
35:   const parsed = new URL(value)
36:   if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') {
37:     throw new Error('Gateway URL must use HTTP(S)')
38:   }
39:   if (!['127.0.0.1', 'localhost', '[::1]'].includes(parsed.hostname)) {
40:     throw new Error(`Gateway URL escaped the loopback boundary: ${parsed.hostname}`)
41:   }
42:   if (!parsed.pathname.endsWith('/sse')) {
43:     throw new Error(`Gateway URL must target /sse: ${parsed.pathname}`)
44:   }
45:   return parsed
46: }
47: 
48: function hasId(message) {
49:   return Object.prototype.hasOwnProperty.call(message, 'id')
50: }
51: 
52: function parseSseBlock(block) {
53:   let event = 'message'
54:   const data = []
55:   for (const line of block.replace(/\r/g, '').split('\n')) {
56:     if (line.startsWith(':')) continue
57:     if (line.startsWith('event:')) {
58:       event = line.slice(6).trim()
59:     } else if (line.startsWith('data:')) {
60:       data.push(line.slice(5).replace(/^ /, ''))
61:     }
62:   }
63:   return { event, data: data.join('\n') }
64: }
65: 
66: class ClassicSseClient {
67:   constructor(url) {
68:     this.url = assertGatewayUrl(url)
69:     this.abort = new AbortController()
70:     this.endpoint = undefined
71:     this.nextId = 0
72:     this.pending = new Map()
73:     this.ready = Promise.withResolvers()
74:     this.readerTask = undefined
75:     this.closed = false
76:   }
77: 
78:   async connect() {
